private boolean stopSendStreaming(RTPManager rtpManager){
  @SuppressWarnings("unchecked") Iterable<SendStream> sendStreams=rtpManager.getSendStreams();
  boolean stoppedAtLeastOneStream=false;
  if (sendStreams != null) {
    for (Object obj : sendStreams) {
      try {
        SendStream stream = (SendStream) obj;
        stream.getDataSource().stop();
        stream.stop();
        stream.close();
      } catch (IOException ex) {
        logger.warn("Failed to stop stream.", ex);
      } catch (RuntimeException ex) {
        logger.warn("Failed to stop stream due to runtime error.", ex);
      }
      stoppedAtLeastOneStream = true;
    }
  }
  return stoppedAtLeastOneStream;
}
